1	package main
2	
3	import (
4		"fmt"
5		"strings"
6		"sync"
7		"time"
8	)
9	
10	// cacheEntry stores a cached postfix result with its expiration time.
11	type cacheEntry struct {
12		Value     string
13		ExpiresAt time.Time
14	}
15	
16	// PostfixCache provides a TTL-based cache for infix-to-postfix conversion results.
17	type PostfixCache struct {
18		mu      sync.RWMutex
19		entries map[string]cacheEntry
20		ttl     time.Duration
21	}
22	
23	// NewPostfixCache creates a new cache with the specified TTL.
24	func NewPostfixCache(ttl time.Duration) *PostfixCache {
25		c := &PostfixCache{
26			entries: make(map[string]cacheEntry),
27			ttl:     ttl,
28		}
29		go c.cleanup()
30		return c
31	}
32	
33	// cleanup periodically removes expired entries.
34	func (c *PostfixCache) cleanup() {
35		ticker := time.NewTicker(c.ttl)
36		defer ticker.Stop()
37		for range ticker.C {
38			c.mu.Lock()
39			now := time.Now()
40			for k, v := range c.entries {
41				if now.After(v.ExpiresAt) {
42					delete(c.entries, k)
43				}
44			}
45			c.mu.Unlock()
46		}
47	}
48	
49	// Get retrieves a cached result if it exists and hasn't expired.
50	func (c *PostfixCache) Get(key string) (string, bool) {
51		c.mu.RLock()
52		defer c.mu.RUnlock()
53		entry, exists := c.entries[key]
54		if !exists || time.Now().After(entry.ExpiresAt) {
55			return "", false
56		}
57		return entry.Value, true
58	}
59	
60	// Set stores a result in the cache with the configured TTL.
61	func (c *PostfixCache) Set(key, value string) {
62		c.mu.Lock()
63		defer c.mu.Unlock()
64		c.entries[key] = cacheEntry{
65			Value:     value,
66			ExpiresAt: time.Now().Add(c.ttl),
67		}
68	}
69	
70	// CacheWithTTL converts an infix expression to postfix (Reverse Polish) notation
71	// using the Shunting Yard algorithm. Results are cached with a TTL to avoid
72	// recomputing previously converted expressions.
73	//
74	// Supports operators: +, -, *, /, ^ (exponentiation)
75	// Supports parentheses for grouping.
76	// Operands can be single-letter variables or multi-digit numbers.
77	func CacheWithTTL(cache *PostfixCache, expression string) (string, error) {
78		// Check cache first
79		if cached, found := cache.Get(expression); found {
80			return cached, nil
81		}
82	
83		// Convert infix to postfix
84		result, err := infixToPostfix(expression)
85		if err != nil {
86			return "", err
87		}
88	
89		// Store in cache
90		cache.Set(expression, result)
91	
92		return result, nil
93	}
94	
95	// operatorPrec returns the precedence level of an operator.
96	func operatorPrec(op string) (int, bool) {
97		switch op {
98		case "+", "-":
99			return 1, false
100		case "*", "/":
101			return 2, false
102		case "^":
103			return 3, true // right-associative
104		default:
105			return 0, false
106		}
107	}
108	
109	// isOperand returns true if the token is an operand (number or variable name).
110	func isOperand(token string) bool {
111		if len(token) == 0 {
112			return false
113		}
114		for _, ch := range token {
115			if !isAlphaNum(ch) {
116				return false
117			}
118		}
119		return true
120	}
121	
122	func isAlphaNum(ch rune) bool {
123		return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9')
124	}
125	
126	// tokenize splits an expression string into tokens (numbers, variables, operators, parens).
127	func tokenize(expression string) ([]string, error) {
128		var tokens []string
129		i := 0
130		for i < len(expression) {
131			ch := expression[i]
132			if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' {
133				i++
134			} else if ch >= '0' && ch <= '9' {
135				j := i
136				for j < len(expression) && expression[j] >= '0' && expression[j] <= '9' {
137					j++
138				}
139				tokens = append(tokens, expression[i:j])
140				i = j
141			} else if (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') {
142				j := i
143				for j < len(expression) && isAlphaNum(rune(expression[j])) {
144					j++
145				}
146				tokens = append(tokens, expression[i:j])
147				i = j
148			} else if ch == '+' || ch == '-' || ch == '*' || ch == '/' || ch == '^' || ch == '(' || ch == ')' {
149				tokens = append(tokens, string(ch))
150				i++
151			} else {
152				return nil, fmt.Errorf("invalid character: %c", ch)
153			}
154		}
155		return tokens, nil
156	}
157	
158	// infixToPostfix converts an infix expression to postfix notation.
159	func infixToPostfix(expression string) (string, error) {
160		tokens, err := tokenize(expression)
161		if err != nil {
162			return "", err
163		}
164	
165		if len(tokens) == 0 {
166			return "", nil
167		}
168	
169		var output []string
170		var opStack []string
171	
172		for _, token := range tokens {
173			if isOperand(token) {
174				output = append(output, token)
175			} else if token == "(" {
176				opStack = append(opStack, token)
177			} else if token == ")" {
178				for len(opStack) > 0 && opStack[len(opStack)-1] != "(" {
179					output = append(output, opStack[len(opStack)-1])
180					opStack = opStack[:len(opStack)-1]
181				}
182				if len(opStack) == 0 {
183					return "", fmt.Errorf("mismatched parentheses: unmatched ')'")
184				}
185				opStack = opStack[:len(opStack)-1] // discard '('
186			} else {
187				// operator
188				prec, rightAssoc := operatorPrec(token)
189				if prec == 0 {
190					return "", fmt.Errorf("unknown operator: %s", token)
191				}
192				for len(opStack) > 0 && opStack[len(opStack)-1] != "(" {
193					top := opStack[len(opStack)-1]
194					topPrec, _ := operatorPrec(top)
195					if topPrec == 0 {
196						break
197					}
198					if topPrec > prec || (topPrec == prec && !rightAssoc) {
199						output = append(output, top)
200						opStack = opStack[:len(opStack)-1]
201					} else {
202						break
203					}
204				}
205				opStack = append(opStack, token)
206			}
207		}
208	
209		for len(opStack) > 0 {
210			top := opStack[len(opStack)-1]
211			opStack = opStack[:len(opStack)-1]
212			if top == "(" {
213				return "", fmt.Errorf("mismatched parentheses: unmatched '('")
214			}
215			output = append(output, top)
216		}
217	
218		return strings.Join(output, " "), nil
219	}
