1	/**
2	 * Math expression parser with TTL-based result caching.
3	 *
4	 * Tokenizes, parses (Shunting-yard → postfix), and evaluates mathematical
5	 * expressions. Results are cached by expression string with a configurable
6	 * time-to-live to avoid redundant computation.
7	 *
8	 * Supported: +, -, *, /, ^, parentheses, negative numbers, decimals.
9	 */
10	
11	// ---------------------------------------------------------------------------
12	// Tokenizer
13	// ---------------------------------------------------------------------------
14	
15	function tokenize(expr) {
16	  const tokens = [];
17	  let i = 0;
18	  while (i < expr.length) {
19	    if (expr[i] === ' ') { i++; continue; }
20	
21	    // Unary minus: insert 0 so it becomes 0 - X (binary), preserving precedence
22	    if (
23	      expr[i] === '-' &&
24	      (tokens.length === 0 || ['(', '+', '-', '*', '/', '^'].includes(tokens[tokens.length - 1]))
25	    ) {
26	      tokens.push('0');
27	      tokens.push('-');
28	      i++;
29	      continue;
30	    }
31	
32	    // Number
33	    if (/\d/.test(expr[i])) {
34	      let num = '';
35	      while (i < expr.length && /\d/.test(expr[i])) { num += expr[i++]; }
36	      if (i < expr.length && expr[i] === '.') {
37	        num += expr[i++];
38	        while (i < expr.length && /\d/.test(expr[i])) { num += expr[i++]; }
39	      }
40	      tokens.push(num);
41	      continue;
42	    }
43	
44	    if ('+-*/^()'.includes(expr[i])) {
45	      tokens.push(expr[i++]);
46	      continue;
47	    }
48	
49	    throw new SyntaxError(`Unexpected character: '${expr[i]}'`);
50	  }
51	  return tokens;
52	}
53	
54	// ---------------------------------------------------------------------------
55	// Shunting-yard parser  (tokens → postfix / RPN)
56	// ---------------------------------------------------------------------------
57	
58	const PRECEDENCE = { '+': 1, '-': 1, '*': 2, '/': 2, '^': 3 };
59	const RIGHT_ASSOC = new Set(['^']);
60	
61	function toPostfix(tokens) {
62	  const output = [];
63	  const ops = [];
64	
65	  for (const tok of tokens) {
66	    if (/^-?\d/.test(tok)) {
67	      output.push(tok);
68	    } else if (tok === '(') {
69	      ops.push(tok);
70	    } else if (tok === ')') {
71	      while (ops.length && ops[ops.length - 1] !== '(') output.push(ops.pop());
72	      if (!ops.length) throw new SyntaxError('Mismatched parentheses');
73	      ops.pop();
74	    } else {
75	      while (
76	        ops.length &&
77	        ops[ops.length - 1] !== '(' &&
78	        (PRECEDENCE[ops[ops.length - 1]] > PRECEDENCE[tok] ||
79	          (PRECEDENCE[ops[ops.length - 1]] === PRECEDENCE[tok] && !RIGHT_ASSOC.has(tok)))
80	      ) {
81	        output.push(ops.pop());
82	      }
83	      ops.push(tok);
84	    }
85	  }
86	
87	  while (ops.length) {
88	    if (ops[ops.length - 1] === '(') throw new SyntaxError('Mismatched parentheses');
89	    output.push(ops.pop());
90	  }
91	
92	  return output;
93	}
94	
95	// ---------------------------------------------------------------------------
96	// Postfix evaluator
97	// ---------------------------------------------------------------------------
98	
99	function evaluate(postfix) {
100	  const stack = [];
101	
102	  for (const tok of postfix) {
103	    if (/^-?\d/.test(tok)) {
104	      stack.push(parseFloat(tok));
105	    } else {
106	      if (stack.length < 2) throw new SyntaxError('Invalid expression');
107	      const b = stack.pop();
108	      const a = stack.pop();
109	      switch (tok) {
110	        case '+': stack.push(a + b); break;
111	        case '-': stack.push(a - b); break;
112	        case '*': stack.push(a * b); break;
113	        case '/':
114	          if (b === 0) throw new RangeError('Division by zero');
115	          stack.push(a / b);
116	          break;
117	        case '^': stack.push(Math.pow(a, b)); break;
118	        default: throw new SyntaxError(`Unknown operator: ${tok}`);
119	      }
120	    }
121	  }
122	
123	  if (stack.length !== 1) throw new SyntaxError('Invalid expression');
124	  return stack[0];
125	}
126	
127	// ---------------------------------------------------------------------------
128	// cache_with_ttl  –  expression cache with time-to-live
129	// ---------------------------------------------------------------------------
130	
131	/**
132	 * Create a math expression evaluator with TTL-based result caching.
133	 *
134	 * @param {object}  opts
135	 * @param {number}  opts.ttlMs        - Cache TTL in milliseconds (default 60 000)
136	 * @param {number}  opts.maxCacheSize - Max cached entries before eviction (default 500)
137	 * @returns {{ eval: (expr: string) => number, cacheSize: number, clearCache: () => void }}
138	 */
139	function cache_with_ttl({ ttlMs = 60000, maxCacheSize = 500 } = {}) {
140	  const cache = new Map(); // key → { value, timestamp }
141	
142	  function evict() {
143	    const now = Date.now();
144	    for (const [key, entry] of cache) {
145	      if (now - entry.timestamp > ttlMs) cache.delete(key);
146	    }
147	    while (cache.size > maxCacheSize) {
148	      cache.delete(cache.keys().next().value);
149	    }
150	  }
151	
152	  return {
153	    /**
154	     * Parse and evaluate a mathematical expression. Results are cached by
155	     * the raw expression string and served from cache when still valid.
156	     *
157	     * @param {string} expr - Infix mathematical expression
158	     * @returns {number}
159	     */
160	    eval(expr) {
161	      const key = expr.trim();
162	      const now = Date.now();
163	      const cached = cache.get(key);
164	      if (cached && now - cached.timestamp <= ttlMs) {
165	        return cached.value;
166	      }
167	
168	      const tokens = tokenize(key);
169	      const postfix = toPostfix(tokens);
170	      const result = evaluate(postfix);
171	
172	      cache.set(key, { value: result, timestamp: now });
173	      evict();
174	      return result;
175	    },
176	
177	    /** Number of cached results. */
178	    get cacheSize() {
179	      evict();
180	      return cache.size;
181	    },
182	
183	    /** Clear all cached results. */
184	    clearCache() {
185	      cache.clear();
186	    },
187	  };
188	}
189	
190	// ---------------------------------------------------------------------------
191	// Tests
192	// ---------------------------------------------------------------------------
193	
194	function runTests() {
195	  let passed = 0;
196	  let failed = 0;
197	  const failures = [];
198	
199	  function assert(cond, desc) {
200	    if (cond) { passed++; console.log(`  PASS  ${desc}`); }
201	    else { failed++; failures.push(desc); console.error(`  FAIL  ${desc}`); }
202	  }
203	
204	  function approx(actual, expected, desc, eps = 1e-9) {
205	    assert(Math.abs(actual - expected) < eps, desc);
206	  }
207	
208	  function assertThrows(fn, desc) {
209	    try { fn(); failed++; failures.push(desc); console.error(`  FAIL  ${desc} (no error)`); }
210	    catch { passed++; console.log(`  PASS  ${desc}`); }
211	  }
212	
213	  function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }
214	
215	  // ── Basic arithmetic ───────────────────────────────────────────────────
216	
217	  console.log('\n=== Basic arithmetic ===');
218	  {
219	    const c = cache_with_ttl();
220	    assert(c.eval('2 + 3') === 5, 'addition');
221	    assert(c.eval('10 - 4') === 6, 'subtraction');
222	    assert(c.eval('3 * 7') === 21, 'multiplication');
223	    assert(c.eval('20 / 5') === 4, 'division');
224	    assert(c.eval('2 ^ 10') === 1024, 'exponentiation');
225	  }
226	
227	  // ── Operator precedence ────────────────────────────────────────────────
228	
229	  console.log('\n=== Operator precedence ===');
230	  {
231	    const c = cache_with_ttl();
232	    assert(c.eval('2 + 3 * 4') === 14, 'mul before add');
233	    assert(c.eval('2 * 3 + 4') === 10, 'mul left side');
234	    assert(c.eval('10 - 2 * 3') === 4, 'mul before sub');
235	    assert(c.eval('2 + 3 * 4 - 5') === 9, 'mixed + - *');
236	    assert(c.eval('2 * 3 + 4 * 5') === 26, 'two muls with add');
237	    assert(c.eval('2 + 3 ^ 2') === 11, 'pow before add');
238	    assert(c.eval('2 * 3 ^ 2') === 18, 'pow before mul');
239	  }
240	
241	  // ── Parentheses ───────────────────────────────────────────────────────
242	
243	  console.log('\n=== Parentheses ===');
244	  {
245	    const c = cache_with_ttl();
246	    assert(c.eval('(2 + 3) * 4') === 20, 'parens override precedence');
