2	 * Math expression parser with TTL-based result caching.
3	 *
4	 * Tokenizes, parses (Shunting-yard → postfix), and evaluates mathematical
5	 * expressions. Results are cached by expression string with a configurable
6	 * time-to-live to avoid redundant computation.
7	 *
8	 * Supported: +, -, *, /, ^, parentheses, negative numbers, decimals.
9	 */
10	
11	// ---------------------------------------------------------------------------
12	// Tokenizer
13	// ---------------------------------------------------------------------------
14	
15	function tokenize(expr) {
16	  const tokens = [];
17	  let i = 0;
18	  while (i < expr.length) {
19	    if (expr[i] === ' ') { i++; continue; }
20	
21	    // Unary minus: insert 0 so it becomes 0 - X (binary), preserving precedence
22	    if (
23	      expr[i] === '-' &&
24	      (tokens.length === 0 || ['(', '+', '-', '*', '/', '^'].includes(tokens[tokens.length - 1]))
25	    ) {
26	      tokens.push('0');
27	      tokens.push('-');
28	      i++;
29	      continue;
30	    }
31	
32	    // Number
33	    if (/\d/.test(expr[i])) {
34	      let num = '';
35	      while (i < expr.length && /\d/.test(expr[i])) { num += expr[i++]; }
36	      if (i < expr.length && expr[i] === '.') {
37	        num += expr[i++];
38	        while (i < expr.length && /\d/.test(expr[i])) { num += expr[i++]; }
39	      }
40	      tokens.push(num);
41	      continue;
42	    }
43	
44	    if ('+-*/^()'.includes(expr[i])) {
45	      tokens.push(expr[i++]);
46	      continue;
47	    }
48	
49	    throw new SyntaxError(`Unexpected character: '${expr[i]}'`);
50	  }
51	  return tokens;
52	}
53	
54	// ---------------------------------------------------------------------------
55	// Shunting-yard parser  (tokens → postfix / RPN)
56	// ---------------------------------------------------------------------------
57	
58	const PRECEDENCE = { '+': 1, '-': 1, '*': 2, '/': 2, '^': 3 };
59	const RIGHT_ASSOC = new Set(['^']);
60	
61	function toPostfix(tokens) {
62	  const output = [];
63	  const ops = [];
64	
65	  for (const tok of tokens) {
66	    if (/^-?\d/.test(tok)) {
67	      output.push(tok);
68	    } else if (tok === '(') {
69	      ops.push(tok);
70	    } else if (tok === ')') {
71	      while (ops.length && ops[ops.length - 1] !== '(') output.push(ops.pop());
72	      if (!ops.length) throw new SyntaxError('Mismatched parentheses');
73	      ops.pop();
74	    } else {
75	      while (
76	        ops.length &&
77	        ops[ops.length - 1] !== '(' &&
78	        (PRECEDENCE[ops[ops.length - 1]] > PRECEDENCE[tok] ||
79	          (PRECEDENCE[ops[ops.length - 1]] === PRECEDENCE[tok] && !RIGHT_ASSOC.has(tok)))
80	      ) {
81	        output.push(ops.pop());
82	      }
83	      ops.push(tok);
84	    }
85	  }
86	
87	  while (ops.length) {
88	    if (ops[ops.length - 1] === '(') throw new SyntaxError('Mismatched parentheses');
89	    output.push(ops.pop());
90	  }
91	
92	  return output;
93	}
