96	// Postfix evaluator
97	// ---------------------------------------------------------------------------
98	
99	function evaluate(postfix) {
100	  const stack = [];
101	
102	  for (const tok of postfix) {
103	    if (/^-?\d/.test(tok)) {
104	      stack.push(parseFloat(tok));
105	    } else {
106	      if (stack.length < 2) throw new SyntaxError('Invalid expression');
107	      const b = stack.pop();
108	      const a = stack.pop();
