137	 * @returns {{ eval: (expr: string) => number, cacheSize: number, clearCache: () => void }}
138	 */
139	function cache_with_ttl({ ttlMs = 60000, maxCacheSize = 500 } = {}) {
140	  const cache = new Map(); // key → { value, timestamp }
141	
142	  function evict() {
143	    const now = Date.now();
144	    for (const [key, entry] of cache) {
145	      if (now - entry.timestamp > ttlMs) cache.delete(key);
146	    }
147	    while (cache.size > maxCacheSize) {
148	      cache.delete(cache.keys().next().value);
149	    }
